# Owned native observations outside the omitted-selector selection change; no compatibility credit.
check<-function(name,expr){tryCatch(cat(if(isTRUE(force(expr)))"PASS" else "FAIL",name,"\n"),error=function(e)cat("ERROR",name,conditionMessage(e),"\n"))}
check("NextMethod explicit extra named argument observation",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x,y)UseMethod("g",1L);g.integer<-function(x,y)NextMethod(y=9L);g.numeric<-function(x,y)list(x=x,y=y,classes=.Class);g("original",2L)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(error = "unused argument (y)"), warnings = character(0))))
check("forwarded missing original with a method default",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x)UseMethod("g",1L);g.integer<-function(x=7L)list(missing=missing(x),value=x,classes=.Class);h<-function(x)g(x);h()}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(error = "argument \"x\" is missing, with no default"),
    warnings = character(0))))
